
const sources={"상류": ["media-613dd8dd9e448050.webp", "media-46aac3eb38b164ba.webp"], "중류": ["media-aee9f8e229c9e494.webp", "media-2410d914fdd9ab6b.webp"], "하류": ["media-bb2d84fa45fd768a.webp", "media-4bdca8b8b125f3bd.webp"], "습지": ["media-756a8a30d9dd9ccd.webp", "media-7be12e53159a3c3e.webp"]};const dialog=document.getElementById('cards');let region='상류';
function page(i){document.getElementById('source').src=sources[region][i];document.getElementById('source').alt=region+' 미션카드 원본 '+(i+1)+'쪽';document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.page)===i)));dialog.scrollTop=0}
document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{region=b.dataset.region;document.getElementById('cardTitle').textContent=region+' 미션카드 · 총 5개';page(0);dialog.showModal()});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>page(Number(b.dataset.page)));document.getElementById('close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
let scale=1;const board=document.getElementById('board');function zoom(n){scale=Math.max(1,Math.min(2.5,n));board.style.width=scale===1?'min(100%,1120px)':Math.round(1120*scale)+'px';document.getElementById('fit').textContent=scale===1?'화면 맞춤':Math.round(scale*100)+'% · 맞춤'}document.getElementById('plus').onclick=()=>zoom(scale+.25);document.getElementById('minus').onclick=()=>zoom(scale-.25);document.getElementById('fit').onclick=()=>zoom(1);document.getElementById('full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{document.getElementById('full').textContent='F11로 전체화면'}};document.addEventListener('fullscreenchange',()=>document.getElementById('full').textContent=document.fullscreenElement?'전체화면 닫기':'전체화면');

const logoMagic=document.getElementById('logoMagic');let magicTimer;
function playMagic(){clearTimeout(magicTimer);logoMagic.classList.remove('play');requestAnimationFrame(()=>requestAnimationFrame(()=>{logoMagic.classList.add('play');magicTimer=setTimeout(()=>logoMagic.classList.remove('play'),4100)}))}
logoMagic.addEventListener('click',playMagic);window.addEventListener('load',playMagic,{once:true});

const guide=document.getElementById('guide'),guideTitle=document.getElementById('guideTitle'),guideBody=document.getElementById('guideBody'),guideActions=document.getElementById('guideActions'),guideFeedback=document.getElementById('guideFeedback'),guideFoot=document.getElementById('guideFoot');let guideStep=0,voiceOn=false,guideReturn=null;
document.querySelector('.otter-portrait').style.backgroundImage='url("'+document.querySelector('#board>img').src+'")';
function sayGuide(){if(!voiceOn||!('speechSynthesis' in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(guideTitle.textContent+'. '+guideBody.textContent);u.lang='ko-KR';u.rate=.95;window.speechSynthesis.speak(u)}
function action(label,fn,primary=false){const b=document.createElement('button');b.textContent=label;if(primary)b.className='guide-primary';b.onclick=fn;guideActions.append(b);return b}
function clearGuideHighlight(){document.querySelectorAll('.tutorial-highlight').forEach(e=>e.classList.remove('tutorial-highlight'));guide.classList.remove('guide-board-step')}
function finishGuide(){clearGuideHighlight();guide.hidden=true;document.getElementById('practiceChip').hidden=true;if('speechSynthesis' in window)window.speechSynthesis.cancel();document.getElementById('helpGuide').focus();document.querySelector('#board').scrollIntoView({block:'start',behavior:'instant'})}
function showGuide(n){guideStep=n;guide.hidden=false;guide.classList.toggle('guide-intro-step',n===0);if(typeof guideLearning!=='undefined')guideLearning.hidden=n!==0;clearGuideHighlight();guideActions.replaceChildren();guideFeedback.textContent='';guideFoot.textContent='연습 안내에서는 실제 게임 진행 기록이 생기지 않아요.';document.querySelectorAll('.guide-step i').forEach((e,i)=>e.classList.toggle('on',i<=n));document.getElementById('practiceChip').hidden=n!==3;
if(n===0){guideTitle.textContent='안녕 친구야 우리 같이 낙동강 탐험을 해보자!';guideBody.innerHTML='<p>나는 낙동강에 살고 있는 <strong>수달이</strong>야. 우리 강에는 어떤 생물들이 살고, 어떤 자연환경이 펼쳐져 있는지 궁금하지?</p><p>수달이와 미션을 해결하면서 내가 사는 낙동강을 알아보고, <strong>소중한 생태계를 지키는 생태 지킴이</strong>가 되어 보자!</p><p><strong>상류·중류·하류·습지에서 생태계칩을 5개씩, 총 20개</strong> 모두 찾으면 돼. 찾은 칩을 보드의 알맞은 자리에 놓으며 낙동강 생태계를 함께 완성해 보자!</p>';const practice=action('② 게임 테스트 연습해보기 →',()=>showGuide(1));practice.classList.add('guide-practice')}
if(n===1){guideTitle.textContent='첫 번째! 상류 카드를 눌러 봐';guideBody.innerHTML='<p><strong>1인용 탐험</strong>에서는 원하는 구역을 골라 남은 미션 중 무작위 문제를 풀어요. 문제를 충분히 읽고 <strong>정답 입력 시작</strong>을 누르면 시간이 흘러요.</p><p>지금은 보드의 <strong>초록색 상류 카드</strong>를 직접 눌러 보자!</p>';guide.classList.add('guide-board-step');const deck=document.querySelector('[data-region="상류"]');deck.classList.add('tutorial-highlight');deck.scrollIntoView({block:'center',behavior:'instant'});action('상류 카드 위치 보기',()=>deck.focus());}
if(n===2){guideTitle.textContent='문제를 읽고 답을 골라 봐';guideBody.innerHTML='<p>연습에서는 버튼으로 골라 봐요. 실제 탐험에서는 <strong>정답을 입력하고 확인</strong>하면 돼요.</p><p>연습 문제: 낙동강 상류의 물살은 하류보다 <strong>빠를까, 느릴까?</strong></p>';action('빠르다',()=>showGuide(3),true);action('느리다',()=>{guideFeedback.textContent='괜찮아! 힌트: 상류는 경사가 급한 곳이 많아. 다시 골라 봐.';if(voiceOn&&'speechSynthesis' in window){window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(guideFeedback.textContent);u.lang='ko-KR';window.speechSynthesis.speak(u)}});}
if(n===3){guideTitle.textContent='맞았어! 생태계칩을 놓았어';guideBody.innerHTML='<p>상류는 경사가 급한 곳이 많아 물살이 대체로 빨라. 정답에 맞는 칩을 찾아 <strong>보드의 알맞은 자리에</strong> 놓는 거야.</p><div class="guide-chip">💧 빠른 물살 · 연습 성공!</div><p>칩은 자동으로 알맞은 칸에 들어가요. 한 구역의 <strong>5개를 모두 모으면 +100p</strong>를 받아요.</p>';action('마지막 방법 알아보기 →',()=>showGuide(4),true)}
if(n===4){guideTitle.textContent='수달이와 탐험할 준비 완료!';guideBody.innerHTML='<p>✓ <strong>입력 시작부터 30초</strong>는 기본 점수, 이후 30초마다 -1p예요.</p><p>✓ 힌트는 -1p. 읽는 동안 멈추고 <strong>다시 입력하면 재개</strong>돼요.</p><p>✓ 힌트 후 다시 틀리면 정답을 읽고 돌아와요. 그때 <strong>점수·칩은 없어요.</strong></p><p>✓ 다시 섞기는 총점 -1p, 0p에서는 그대로예요.</p><p>✓ <strong>200p 또는 칩 10개</strong>를 모으면 동의한 참가자는 기록을 남길 수 있어요.</p>';guideFoot.textContent='연습은 실제 점수에 영향을 주지 않아요. 20칩을 모두 찾으면 전체 복원 영웅 세리머니가 열려요.';action('나의 탐험 시작 →',finishGuide,true);action('처음부터 다시 연습',()=>showGuide(0))}
guideTitle.focus({preventScroll:true});sayGuide()}
document.getElementById('skipGuide').onclick=finishGuide;document.getElementById('helpGuide').onclick=()=>showGuide(0);document.getElementById('voiceGuide').onclick=()=>{if(!('speechSynthesis' in window)){guideFeedback.textContent='이 브라우저에서는 음성 안내를 지원하지 않아. 글 안내로 함께하자!';return}voiceOn=!voiceOn;document.getElementById('voiceGuide').textContent=voiceOn?'음성 끄기':'음성 켜기';document.getElementById('voiceGuide').setAttribute('aria-pressed',String(voiceOn));if(voiceOn)sayGuide();else window.speechSynthesis.cancel()};
document.querySelectorAll('[data-region]').forEach(b=>b.addEventListener('click',e=>{if(!guide.hidden){e.stopImmediatePropagation();if(guideStep===1&&b.dataset.region==='상류')showGuide(2)}},true));
guide.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();finishGuide()}if(e.key==='Tab'){const focusables=[...guide.querySelectorAll('button')];if(guideStep===1)focusables.push(document.querySelector('[data-region="상류"]'));const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
