const MISSION_DATA=[{"id": "1-1", "region": "상류", "number": 1, "chip": "좁은 강폭", "question": "낙동강 상류의 강 폭은 하류보다 넓을까요, 좁을까요?", "hint": "상류는 주로 산과 계곡 사이를 흘러요.", "answer": "(강 폭이) 좁다", "explanation": "낙동강 상류는 산지가 많아 강의 폭이 대체로 좁습니다. 하류로 갈수록 여러 강물이 합쳐지면서 강의 폭이 넓어집니다.", "source": "상류1.pdf", "sourceCard": 1}, {"id": "1-2", "region": "상류", "number": 2, "chip": "빠른 물살", "question": "낙동강 상류의 물살은 하류보다 빠를까요, 느릴까요?", "hint": "상류는 경사가 급한 곳이 많아요.", "answer": "(물살이) 빠르다", "explanation": "낙동강 상류는 경사가 급한 곳이 많아 물살이 대체로 빠릅니다. 물이 흐르면서 돌과 자갈을 움직이기도 합니다.", "source": "상류1.pdf", "sourceCard": 2}, {"id": "1-3", "region": "상류", "number": 3, "chip": "수달", "question": "낙동강 상류의 강가에 살며, 몸이 털로 덮여 있고 발에 물갈퀴가 있어 헤엄을 잘 치며 물고기를 잡아먹는 동물은?", "hint": "몸이 길쭉하고 꼬리가 길며, 물속과 땅 위에서 모두 활동할 수 있어요.", "answer": "수달", "explanation": "수달은 강이나 하천 주변에서 살아가며 물고기 등을 잡아먹습니다. 몸이 털로 덮여 있고 발에 물갈퀴가 있어 헤엄을 잘 칩니다. 우리나라에서 천연기념물로 보호받는 동물입니다.", "source": "상류1.pdf", "sourceCard": 3}, {"id": "1-4", "region": "상류", "number": 4, "chip": "쉬리", "question": "낙동강의 맑은 물에 살며, 몸에 노란색과 검은색 줄무늬가 있는 물고기는 무엇일까요?", "hint": "우리나라 하천에 사는 물고기로, 이름은 두 글자이고 ‘쉬’로 시작해요.", "answer": "쉬리", "explanation": "쉬리는 맑은 물이 흐르고 돌과 자갈이 많은 하천에서 살아가는 우리나라의 민물고기입니다.", "source": "상류2.pdf", "sourceCard": 1}, {"id": "1-5", "region": "상류", "number": 5, "chip": "이끼", "question": "낙동강 상류의 습한 바위나 돌 위에서 볼 수 있으며, 작은 초록색 식물들이 모여 자라는 것은 무엇일까요?", "hint": "꽃이 피지 않고 포자로 번식하며, 이름은 두 글자예요.", "answer": "이끼", "explanation": "이끼는 물기가 많고 그늘진 바위나 땅에서 자라는 작은 식물입니다. 낙동강 상류의 계곡처럼 습하고 서늘한 곳에서도 볼 수 있으며, 물과 습기를 흡수하고 작은 생물들에게 살아갈 공간을 제공하기도 합니다.", "source": "상류2.pdf", "sourceCard": 2}, {"id": "2-1", "region": "중류", "number": 1, "chip": "둥근 돌", "question": "낙동강 중류에서 강물을 따라 이동한 돌은 상류의 돌에 비해 모양이 대체로 어떻게 다를까요?", "hint": "돌이 강물을 따라 이동하면서 서로 부딪히고 뾰족한 부분이 깎여요.", "answer": "더 둥글고 매끄럽다.", "explanation": "돌은 강물을 따라 이동하면서 서로 부딪히고 깎여 점차 둥글고 매끄러워집니다. 그래서 중류에서는 물에 오래 운반된 둥근 돌을 볼 수 있습니다.", "source": "중류1.pdf", "sourceCard": 1}, {"id": "2-2", "region": "중류", "number": 2, "chip": "흰목물떼새", "question": "낙동강 중류의 모래밭이나 자갈밭에서 살아가며, 목에 흰색 띠가 있고 땅 위에 알을 낳는 작은 새는 무엇일까요?", "hint": "이름은 다섯 글자이며, ‘물떼새’라는 말이 들어가요.", "answer": "흰목물떼새", "explanation": "흰목물떼새는 강가의 모래밭이나 자갈밭에서 먹이를 찾고 알을 낳습니다. 사람들이 새집을 함부로 밟지 않는 것이 중요합니다.", "source": "중류1.pdf", "sourceCard": 2}, {"id": "2-3", "region": "중류", "number": 3, "chip": "왜가리", "question": "낙동강 중류의 물가에서 긴 다리로 서서 물고기를 기다리다가, 긴 부리로 재빨리 잡아먹는 새는 무엇일까요?", "hint": "몸이 회색빛이고 목과 다리가 길어요. 이름은 세 글자예요.", "answer": "왜가리", "explanation": "왜가리는 강이나 하천의 얕은 물에서 물고기 등을 잡아먹습니다. 긴 다리와 뾰족한 부리는 물속에서 먹이를 잡는 데 도움이 됩니다.", "source": "중류1.pdf", "sourceCard": 3}, {"id": "2-4", "region": "중류", "number": 4, "chip": "물억새", "question": "낙동강 중류의 강가에서 무리 지어 자라며, 가을이 되면 은빛 꽃이삭이 바람에 흔들리는 풀은 무엇일까요?", "hint": "억새와 비슷하게 생겼지만 물가의 습한 땅에서 잘 자라요. 이름은 세 글자이며 ‘물’로 시작해요.", "answer": "물억새", "explanation": "물억새는 강가의 습한 땅에서 무리 지어 자랍니다. 여러 곤충과 작은 동물에게 숨을 곳을 제공하고, 뿌리는 강가의 흙이 쓸려 내려가는 것을 줄이는 데 도움을 줍니다.", "source": "중류2.pdf", "sourceCard": 1}, {"id": "2-5", "region": "중류", "number": 5, "chip": "피라미", "question": "낙동강 중류에서 여러 마리가 무리 지어 헤엄치며, 몸이 가늘고 은빛을 띠는 작은 민물고기는 무엇일까요?", "hint": "우리나라 강에서 흔히 볼 수 있는 물고기로, 이름은 세 글자이며 ‘피’로 시작해요.", "answer": "피라미", "explanation": "피라미는 강이나 하천에서 무리 지어 살아가는 민물고기입니다. 작은 수생생물이나 조류 등을 먹으며 다른 동물의 먹이가 되기도 합니다.", "source": "중류2.pdf", "sourceCard": 2}, {"id": "3-1", "region": "하류", "number": 1, "chip": "모래톱", "question": "낙동강 하류에는 강물이 운반한 모래가 쌓여 만들어진 모래밭이나 작은 모래섬이 있습니다. 이것을 무엇이라고 할까요?", "hint": "강물이 운반한 모래가 쌓여 만들어져요. 이름은 세 글자이며 ‘모래’로 시작해요.", "answer": "모래톱", "explanation": "모래톱은 강물이 운반한 모래가 쌓여 만들어집니다. 낙동강 하류의 모래톱은 철새들이 쉬거나 먹이를 찾는 중요한 장소입니다.", "source": "하류1.pdf", "sourceCard": 1}, {"id": "3-2", "region": "하류", "number": 2, "chip": "큰고니", "question": "겨울이 되면 낙동강 하류를 찾아오는 철새로, 몸이 크고 하얀색이며 목이 길고 부리에 노란색과 검은색이 있는 새는 무엇일까요?", "hint": "백조라고도 불리는 새의 한 종류예요. 이름은 세 글자이며 ‘큰’으로 시작해요.", "answer": "큰고니", "explanation": "큰고니는 겨울을 보내기 위해 낙동강 하구를 찾아오는 겨울철새입니다. 물속의 수생식물 등을 먹으며, 습지와 모래톱에서 쉬기도 합니다.", "source": "하류1.pdf", "sourceCard": 2}, {"id": "3-3", "region": "하류", "number": 3, "chip": "뱀장어", "question": "낙동강 하류에서도 볼 수 있으며, 몸이 뱀처럼 길고 강에서 자라다가 알을 낳기 위해 먼 바다로 이동하는 물고기는 무엇일까요?", "hint": "몸이 길고 미끄러우며, 이름은 세 글자이고 ‘뱀’으로 시작해요.", "answer": "뱀장어", "explanation": "뱀장어는 강이나 하구에서 성장하다가 알을 낳기 위해 먼 바다로 이동합니다. 강과 바다가 연결되어 있어야 살아가는 데 필요한 이동을 할 수 있습니다.", "source": "하류1.pdf", "sourceCard": 3}, {"id": "3-4", "region": "하류", "number": 4, "chip": "재첩", "question": "낙동강 하류의 모래나 진흙 속에 살며, 단단한 껍데기 두 장으로 몸을 보호하고 물속의 작은 먹이를 걸러 먹는 조개는 무엇일까요?", "hint": "크기가 작은 조개의 한 종류로, 이름은 두 글자이며 ‘재’로 시작해요.", "answer": "재첩", "explanation": "재첩은 강바닥의 모래나 진흙 속에 사는 작은 조개류입니다. 물속의 작은 먹이 입자를 걸러 먹으며, 물의 흐름과 염분 등 서식 환경의 영향을 받습니다.", "source": "하류2.pdf", "sourceCard": 1}, {"id": "3-5", "region": "하류", "number": 5, "chip": "갈대", "question": "낙동강 하류의 물가에서 무리 지어 자라며, 키가 크고 가을이 되면 줄기 끝에 갈색빛 꽃이삭이 피는 식물은 무엇일까요?", "hint": "바람이 불면 긴 줄기가 흔들리며, 새와 작은 동물들이 몸을 숨기기도 해요. 이름은 두 글자예요.", "answer": "갈대", "explanation": "갈대는 강가나 습지의 물이 얕은 곳에서 무리 지어 자랍니다. 새와 작은 동물들에게 숨을 곳을 제공하고, 뿌리는 강가의 흙이 쓸려 내려가는 것을 줄여 줍니다.", "source": "하류2.pdf", "sourceCard": 2}, {"id": "4-1", "region": "습지", "number": 1, "chip": "습지", "question": "강이나 하천 주변에 있으며, 땅에 물이 많고 여러 생물이 살아가는 곳은 어디일까요?", "hint": "빗물을 저장해 홍수를 줄여 주고, 다양한 동식물의 보금자리가 되는 곳이에요. 이름은 두 글자예요.", "answer": "습지", "explanation": "습지는 물이 고여 있거나 땅이 물에 젖어 있는 곳입니다. 빗물을 저장하고 천천히 흘려보내 홍수 피해를 줄여 줍니다. 또한 다양한 동식물이 살아가는 소중한 서식지입니다.", "source": "습지1.pdf", "sourceCard": 1}, {"id": "4-2", "region": "습지", "number": 2, "chip": "맹꽁이", "question": "낙동강 주변의 습지나 논에서 볼 수 있으며 몸이 둥글고 비가 많이 오는 여름철에 ‘맹꽁 맹꽁’ 소리를 내는 동물은 무엇일까요?", "hint": "이름은 세 글자이며, 울음소리에서 이름이 유래했어요.", "answer": "맹꽁이", "explanation": "맹꽁이는 습지나 논처럼 물이 고이는 곳 주변에서 살아가는 양서류입니다. 평소에는 땅속에 숨어 지내다가 비가 많이 오는 시기에 활동하며, 물이 고인 곳에 알을 낳습니다.", "source": "습지1.pdf", "sourceCard": 2}, {"id": "4-3", "region": "습지", "number": 3, "chip": "재두루미", "question": "겨울철 낙동강 하구에 찾아오는 철새로, 몸은 회색이고 머리와 목의 일부가 흰색인 새는 무엇일까요?", "hint": "이름은 네 글자이며, ‘두루미’라는 말이 들어가요.", "answer": "재두루미", "explanation": "재두루미는 겨울을 나기 위해 우리나라를 찾아오는 철새입니다. 습지와 주변 농경지에서 먹이를 찾고 휴식을 취하므로 안전한 서식지를 보호하는 것이 중요합니다.", "source": "습지1.pdf", "sourceCard": 3}, {"id": "4-4", "region": "습지", "number": 4, "chip": "가시연꽃", "question": "습지의 물 위에 크고 둥근 잎을 띄우며, 잎과 줄기에 가시가 있는 식물은 무엇일까요?", "hint": "이름은 네 글자이며 ‘가시’와 ‘연꽃’이라는 말이 합쳐져 있어요.", "answer": "가시연꽃", "explanation": "가시연꽃은 물의 흐름이 느리거나 고여 있는 습지에서 자라는 수생식물입니다. 크고 둥근 잎이 물 위에 떠 있으며, 잎과 줄기에 가시가 있는 것이 특징입니다.", "source": "습지2.pdf", "sourceCard": 1}, {"id": "4-5", "region": "습지", "number": 5, "chip": "물방개", "question": "습지나 연못의 물속에서 살며 몸이 타원형이고 뒷다리를 노처럼 움직여 헤엄치는 곤충은 무엇일까요?", "hint": "이름은 세 글자이며, ‘물’로 시작해요.", "answer": "물방개", "explanation": "물방개는 습지나 연못의 물속에서 살아가는 수서곤충입니다. 뒷다리에 난 털을 이용해 헤엄을 잘 치며, 작은 수중동물 등을 먹고 살아갑니다.", "source": "습지2.pdf", "sourceCard": 2}];
const STORAGE_KEY='nakdong-missions-v1';let savedMissions=null,storageAvailable=true;try{savedMissions=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')}catch{storageAvailable=false}
let missionGame=new MissionGame(MISSION_DATA,savedMissions);let shownHint=false,shownAnswer=false,viewingCompleted=false;let revealedMissionToReturn=null;
const missionDialog=document.getElementById('missionDialog'),missionContent=document.getElementById('missionContent'),missionTitle=document.getElementById('missionTitle');
const regionColors={'상류':'#2d7a40','중류':'#216fb1','하류':'#b76819','습지':'#783e9d'};
function persistMissions(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(missionGame.serialize()))}catch{storageAvailable=false}if(!storageAvailable)document.getElementById('saveNote').textContent='현재 브라우저에서 저장할 수 없어요. 창을 닫으면 진행이 사라질 수 있어요.'}
function refreshMissions(){const count=missionGame.completed.size;document.getElementById('missionProgress').textContent=count===20?'🎉 낙동강 생태계 복원 성공!':'🌿 함께 복원한 생태계 '+count+' / 20';document.getElementById('missionMeter').value=count;const completedCounter=document.getElementById('completedCount');if(completedCounter)completedCounter.textContent='완료 '+count+'장';document.querySelectorAll('[data-region]').forEach(b=>{let badge=b.querySelector('.deck-count');if(!badge){badge=document.createElement('span');badge.className='deck-count';b.append(badge)}const left=missionGame.remaining(b.dataset.region);badge.textContent=left?'남은 미션 '+left+'장':'5장 모두 완료';b.setAttribute('aria-label',b.dataset.region+' 미션카드, 남은 '+left+'장')});const layer=document.getElementById('placedChips');layer.replaceChildren();for(const id of missionGame.completed){const m=missionGame.byId.get(id);const ri=['상류','중류','하류','습지'].indexOf(m.region);let xs=[[26.2,35.1,44,52.9,61.8],[68.5,59.6,50.7,41.8,32.9],[24.7,33.6,42.5,51.4,60.3],[66.9,58,49.1,40.2,31.3]][ri];const ys=[28.5,45.3,70.1,87.6];const b=document.createElement('button');b.className='placed-chip';b.style.left=xs[m.number-1]+'%';b.style.top=ys[ri]+'%';b.style.setProperty('--chip-color',regionColors[m.region]);const icon=document.createElement('small');icon.textContent='✓ 복원';const chipImage=document.createElement('img');chipImage.src=CHIP_ASSETS[m.id].image;chipImage.alt=m.region+' 생태계칩 '+m.chip;chipImage.draggable=false;b.append(chipImage);b.setAttribute('aria-label',m.region+' '+m.chip+' 완료 카드 다시 보기');b.onclick=()=>showSingleMission(m,true);layer.append(b)}persistMissions()}
function openMissionDialog(){missionDialog.classList.toggle('chip-review-dialog',Boolean(missionContent.querySelector('.chip-review-layout')));if(!missionDialog.open)missionDialog.showModal();missionDialog.scrollTop=0}


function finishRevealedMission(){const m=revealedMissionToReturn;if(!m)return;revealedMissionToReturn=null;discardMissionClock(m);if(missionGame.active===m.id)missionGame.returnCard();shownAnswer=false;shownHint=false;refreshMissions();}

