if(answerView){button('처음으로',()=>{finishRevealedMission();missionDialog.close()},true)}else if(!review&&!shownHint){button('힌트 보기 · -1점',()=>{openTimedHint(m);shownHint=true;showSingleMission(m)});button('정답 보기 · 0점',()=>{revealMissionAnswer(m);shownAnswer=true;showSingleMission(m)});button('못 맞혔어요 · 다시 섞기 · -1p',()=>{if(missionGame.active!==m.id||chipFlightBusy)return;const deducted=applyShufflePenalty();discardMissionClock(m);missionGame.returnCard();refreshMissions();missionDialog.close();announceMission(deducted?'다시 섞기 -1p · 현재 '+missionTotalPoints()+'p. 카드를 돌려놓았어요.':'현재 0p · 추가 감점 없이 카드를 돌려놓았어요.')})}else if(review)button('처음으로',()=>missionDialog.close(),true);if(!buttons.childElementCount)buttons.remove();
