function drawMission(r){const active=missionGame.byId.get(missionGame.active);if(active&&active.region!==r){showRegionSwitch(active,r);return}const wasActive=missionGame.active;const m=missionGame.draw(r);if(m&&!wasActive)missionWrongAttempts.set(m.id,0);if(!m){showMissionCollection(r);return}shownHint=false;shownAnswer=false;refreshMissions();showSingleMission(m)}
