const POINT_BASE={'상류':18,'중류':21,'하류':26,'습지':35};const POINT_KEY='nakdong-points-v1';let pointsState={awards:{},clocks:{}};try{const v=JSON.parse(localStorage.getItem(POINT_KEY)||'null');if(v&&v.awards&&v.clocks)pointsState=v}catch{}
const totalBadge=document.createElement('span');totalBadge.className='points-total';totalBadge.id='pointsTotal';totalBadge.setAttribute('aria-live','polite');document.getElementById('missionProgress').after(totalBadge);
// Existing completed missions predate timing: preserve them at their regional base score.
for(const id of missionGame.completed){if(!Number.isFinite(pointsState.awards[id]))pointsState.awards[id]=POINT_BASE[missionGame.byId.get(id).region]}
for(const c of Object.values(pointsState.clocks)){c.elapsed=Math.min(120000,Math.max(0,Number(c.elapsed)||0));c.since=Date.now();c.paused=true;c.pauseReason='closed'}
function savePoints(){try{localStorage.setItem(POINT_KEY,JSON.stringify(pointsState))}catch{}const total=missionTotalPoints();totalBadge.textContent='🌊 낙동강 살리기 '+total+'점'}
function clockFor(m){let c=pointsState.clocks[m.id];if(!c||!Number.isFinite(c.elapsed)||!Number.isFinite(c.since)){c={elapsed:0,since:Date.now(),paused:true,pauseReason:'ready',started:false,hinted:false,locked:null};pointsState.clocks[m.id]=c}return c}
function elapsedClock(c){return Math.min(120000,Math.max(0,c.elapsed+(c.paused?0:Date.now()-c.since)))}
function scoreAt(m,c){if(c.revealed)return 0;const ms=elapsedClock(c);const penalty=ms<=30000?0:Math.min(3,Math.ceil((ms-30000)/30000));return Math.max(0,POINT_BASE[m.region]-penalty-(c.hinted?1:0))}
function mountMissionTimer(m){const c=clockFor(m);c.since=Date.now();if(c.started===undefined)c.started=c.elapsed>0;c.paused=Boolean(c.revealed||!c.started||shownHint||document.hidden);c.pauseReason=c.revealed?'revealed':!c.started?'ready':shownHint?'hint':document.hidden?'hidden':null;const box=document.createElement('div');box.className='timer-box';box.id='missionTimer';box.dataset.missionId=m.id;box.setAttribute('role','timer');const value=document.createElement('strong');value.id='timerSeconds';const possible=document.createElement('span');possible.id='timerPoints';const help=document.createElement('small');help.textContent='30초 이내 만점 · 이후 30초마다 -1점 · 120초 후 시간 감점 고정 · 힌트 -1점 · 정답 공개 0점';const headline=document.createElement('div');headline.className='timer-headline';headline.append(value,possible);const track=document.createElement('div');track.className='mission-timeline';track.setAttribute('role','progressbar');track.setAttribute('aria-label','문항 경과 시간');track.setAttribute('aria-valuemin','0');track.setAttribute('aria-valuemax','120');for(let i=0;i<4;i++){const segment=document.createElement('div');segment.className='timeline-segment';segment.innerHTML='<span>'+i*30+'–'+(i+1)*30+'초</span><b class="timeline-score"></b>';track.append(segment)}const needle=document.createElement('i');needle.className='timeline-needle';needle.setAttribute('aria-hidden','true');track.append(needle);box.append(headline,track,help);document.querySelector('.answer-test').before(box);updateMissionTimer();savePoints()}
function updateMissionTimer(){const box=document.getElementById('missionTimer');if(!box||!missionDialog.open)return;const m=missionGame.byId.get(box.dataset.missionId);if(!m||missionGame.completed.has(m.id))return;const c=clockFor(m),ms=elapsedClock(c);box.className='timer-box'+(c.paused?' paused':ms>=120000?' frozen':'');document.getElementById('timerSeconds').textContent=(c.revealed?'정답 공개 · 학습 모드':!c.started?'문제 읽기 · 입력 시작 전':ms>=120000?'120초 완료 · 시간 감점 -3점 적용':(ms<30000?'만점까지 ':'다음 감점까지 ')+Math.ceil((30000-ms%30000)/1000)+'초 · 경과 '+Math.floor(ms/1000)+'초')+(c.paused&&!c.revealed?(c.pauseReason==='hint'?' · 힌트 중 일시정지':c.pauseReason==='ready'?' · 준비되면 시작':' · 일시정지'):'');document.getElementById('timerPoints').textContent=c.revealed?'이전에 정답을 확인한 문항이에요 · 이번 문항은 0점':'지금 정답이면 '+scoreAt(m,c)+'점 / 기본 '+POINT_BASE[m.region]+'점';const stage=ms<=30000?0:ms<=60000?1:ms<=90000?2:3;const track=box.querySelector('.mission-timeline');track.style.setProperty('--elapsed',Math.min(100,ms/1200)+'%');track.setAttribute('aria-valuenow',String(Math.floor(ms/1000)));track.setAttribute('aria-valuetext',Math.floor(ms/1000)+'초 경과, 현재 '+scoreAt(m,c)+'점'+(c.paused?' 일시정지':''));track.querySelectorAll('.timeline-segment').forEach((seg,i)=>{seg.classList.toggle('current',i===stage);seg.classList.toggle('passed',i<stage);seg.querySelector('b').textContent=(c.revealed?0:Math.max(0,POINT_BASE[m.region]-i-(c.hinted?1:0)))+'p'});box.classList.toggle('hint-paused',c.pauseReason==='hint')}
function openTimedHint(m){const c=clockFor(m);c.elapsed=elapsedClock(c);c.since=Date.now();c.paused=true;c.pauseReason='hint';c.hinted=true;savePoints()}
function closeTimedHint(m){const c=clockFor(m);c.since=Date.now();c.paused=Boolean(c.revealed||document.hidden);c.pauseReason=c.revealed?'revealed':document.hidden?'hidden':null;savePoints()}
function discardMissionClock(m){const c=clockFor(m);c.elapsed=elapsedClock(c);c.since=Date.now();c.paused=true;c.pauseReason='closed';savePoints()}
function revealMissionAnswer(m){const c=clockFor(m);c.elapsed=elapsedClock(c);c.since=Date.now();c.paused=true;c.revealed=true;c.locked=null;pointsState.learningReviews=Array.from(new Set([...(pointsState.learningReviews||[]),m.id]));savePoints()}
function lockMissionPoints(m){const c=clockFor(m);if(c.locked===null)c.locked=scoreAt(m,c);savePoints()}
function settleMissionPoints(m){const c=clockFor(m);const earned=c.locked===null?scoreAt(m,c):c.locked;pointsState.awards[m.id]=earned;pointsState.history=pointsState.history||{};pointsState.history[m.id]={hinted:Boolean(c.hinted),wrongCount:c.wrongCount||0};delete pointsState.clocks[m.id];return earned}
function showPointReward(earned){savePoints();const popup=document.createElement('div');popup.className='point-reward';popup.setAttribute('role','status');const label=document.createElement('span');label.textContent=earned===0?'학습 완료 · 정답을 확인했어요':'낙동강 살리기 포인트';const num=document.createElement('strong');num.textContent='+'+earned+'점';popup.append(label,num);document.body.append(popup);setTimeout(()=>popup.remove(),2800)}
function resetPoints(){pointsState={awards:{},clocks:{}};savePoints()}
missionDialog.addEventListener('close',()=>{finishRevealedMission();pauseSolvingClocks('closed');savePoints()});
setInterval(updateMissionTimer,200);window.addEventListener('pagehide',()=>{pauseSolvingClocks('hidden');savePoints()});savePoints();

for(const button of document.querySelectorAll('[data-region]')){const label=button.querySelector('.dock-label');const value=document.createElement('span');value.className='region-base-points';value.textContent='+'+POINT_BASE[button.dataset.region]+'p';label.append(value)}
const dockScore=document.createElement('div');dockScore.className='dock-current-score';dockScore.setAttribute('role','status');dockScore.setAttribute('aria-label','현재 낙동강 살리기 점수');const scoreLabel=document.createElement('span');scoreLabel.textContent='현재 점수';const scoreNumber=document.createElement('strong');scoreNumber.id='dockScoreNumber';const scoreMax=document.createElement('small');scoreMax.textContent='';dockScore.append(scoreLabel,scoreNumber,scoreMax);dock.append(dockScore);
const originalSavePoints=savePoints;savePoints=function(){originalSavePoints();const total=missionTotalPoints();scoreNumber.textContent=total+'p'};savePoints();fitCompactBoard();

const RESTORE_RANKS=[{points:100,title:'맑은 물 지킴이',icon:'💧'},{points:200,title:'물고기 친구 지킴이',icon:'🐟'},{points:300,title:'강가 숲 지킴이',icon:'🌳'},{points:400,title:'습지 생명 수호대장',icon:'🌾'},{points:500,title:'낙동강 생태계 복원 영웅',icon:'🏅'}];
function restorationRank(total,completed){if(completed>=20)return 4;let result=-1;RESTORE_RANKS.forEach((r,i)=>{if(total>=r.points)result=i});return result}
const rankStrip=document.createElement('div');rankStrip.className='rank-strip';const rankBadge=document.createElement('button');rankBadge.className='rank-badge';rankBadge.id='restorationRank';rankBadge.setAttribute('aria-label','현재 직위와 전체 승급 단계 보기');const rankNext=document.createElement('span');rankNext.className='rank-next';rankNext.id='rankNext';rankStrip.append(rankBadge,rankNext);document.querySelector('.mission-status').after(rankStrip);
const rankModal=document.createElement('section');rankModal.className='rank-celebration';rankModal.hidden=true;rankModal.setAttribute('role','dialog');rankModal.setAttribute('aria-modal','true');rankModal.setAttribute('aria-labelledby','rankTitle');rankModal.innerHTML='<div class="rank-certificate"><span class="rank-icon" id="rankIcon" aria-hidden="true"></span><div class="rank-earned" id="rankEarned"></div><h2 id="rankTitle"></h2><p id="rankMessage"></p><button id="closeRank">멋져요! 탐험 계속하기</button></div>';document.body.append(rankModal);
let rankTimer=null;let lastRank=-1;try{const n=Number(localStorage.getItem('nakdong-rank-v1'));if(Number.isInteger(n)&&n>=-1&&n<=4)lastRank=n}catch{}
let rankFocus=null;
function closeRank(){rankModal.hidden=true;(rankFocus&&rankFocus.isConnected?rankFocus:rankBadge).focus({preventScroll:true})}
document.getElementById('closeRank').onclick=closeRank;rankModal.addEventListener('keydown',e=>{if(e.key==='Escape')closeRank();if(e.key==='Tab'){e.preventDefault();document.getElementById('closeRank').focus()}});
function celebrateRank(index,total,full){const r=RESTORE_RANKS[index];rankFocus=document.activeElement;document.getElementById('rankIcon').textContent=r.icon;document.getElementById('rankEarned').textContent=index===4&&full&&total<500?'생태계칩 20개 복원 완료!':r.points+'p 달성!';document.getElementById('rankTitle').textContent=r.title+' 승급!';document.getElementById('rankMessage').textContent=index===4?'수달이와 힘을 모아 낙동강 생태계를 복원했어요. 여러분은 낙동강 생태계 복원 영웅입니다!':'수달이와 힘을 모아 낙동강을 지키고 있어요. 새로운 직위를 획득했어요!';rankModal.querySelectorAll('.rank-confetti').forEach(e=>e.remove());for(let i=0;i<16;i++){const confetti=document.createElement('i');confetti.className='rank-confetti';confetti.style.setProperty('--left',(i*6.2)+'%');confetti.style.setProperty('--color',['#e7bf46','#70b685','#72b9d5','#d893b3'][i%4]);confetti.style.setProperty('--delay',(i%5*.14)+'s');rankModal.firstElementChild.append(confetti)}rankModal.hidden=false;document.getElementById('closeRank').focus()}
function updateRestorationRank(){const total=missionTotalPoints();const full=missionGame.completed.size>=20;const level=restorationRank(total,missionGame.completed.size);rankBadge.setAttribute('aria-label','점수 직위 · 전체 복원 달성과 별도로 승급해요');rankBadge.textContent=level<0?'🌱 새싹 복원대원':RESTORE_RANKS[level].icon+' '+RESTORE_RANKS[level].title;rankNext.textContent=level===4?'최고 직위 달성!': '다음 직위까지 '+(RESTORE_RANKS[level+1].points-total)+'p';if(level>lastRank){lastRank=level;try{localStorage.setItem('nakdong-rank-v1',String(level))}catch{}clearTimeout(rankTimer);rankTimer=setTimeout(()=>{if(missionGame.completed.size<20)celebrateRank(level,total,full)},3300)}else if(level<lastRank){lastRank=level;clearTimeout(rankTimer);rankModal.hidden=true;try{localStorage.setItem('nakdong-rank-v1',String(level))}catch{}}}
rankBadge.onclick=()=>{missionTitle.textContent='낙동강 생태계 복원 직위';missionContent.replaceChildren();const total=missionTotalPoints();const level=restorationRank(total,missionGame.completed.size);const intro=document.createElement('p');intro.className='mission-note';intro.textContent='이것은 점수에 따른 직위예요. 500p부터 최고 직위이며, 별도로 칩 20개를 모으면 전체 복원 완료 세리머니가 열려요.';missionContent.append(intro);RESTORE_RANKS.forEach((r,i)=>{const row=document.createElement('div');row.className='rank-list-row'+(i<=level?' achieved':'');const name=document.createElement('span');name.textContent=r.icon+' '+r.title;const score=document.createElement('span');score.textContent=i<=level?'✓ 달성':r.points+'p';row.append(name,score);missionContent.append(row)});openMissionDialog()};
const rankSavePoints=savePoints;savePoints=function(){rankSavePoints();updateRestorationRank()};updateRestorationRank();fitCompactBoard();

