const LEARNING_ENVIRONMENT=[{"id": "1-1", "name": "좁은 강폭", "region": "상류", "title": "산과 계곡 사이를 흐르는 강", "body": "상류는 산과 계곡 사이로 흐르는 곳이 많아, 하류에 비해 강폭이 대체로 좁아요. 하류로 갈수록 여러 지류가 합쳐져 강이 넓어져요.", "key": "강폭은 강을 가로지르는 너비예요. 상류 = 대체로 좁은 강폭", "question": "상류의 강폭은 하류보다 대체로 넓을까요, 좁을까요?", "answer": "대체로 좁아요. 단, 강폭은 지형과 물의 양에 따라 달라질 수 있어요.", "source": "상류1.pdf", "sourceCard": 1}, {"id": "1-2", "name": "빠른 물살", "region": "상류", "title": "경사를 따라 힘차게 흐르는 물", "body": "상류는 경사가 급한 곳이 많아 물살이 대체로 빨라요. 흐르는 물은 돌과 자갈을 움직이기도 해요.", "key": "급한 경사 → 대체로 빠른 물살", "question": "상류의 물살이 대체로 빠른 까닭은 무엇일까요?", "answer": "경사가 급한 곳이 많기 때문이에요. 실제 유속은 수량과 지형 등에 따라서도 달라져요.", "source": "상류1.pdf", "sourceCard": 2}, {"id": "2-1", "name": "둥근 돌", "region": "중류", "title": "돌에 남은 강물 여행의 흔적", "body": "강물을 따라 이동하는 돌은 서로 부딪히고 깎여요. 뾰족한 부분이 닳으면서 점차 둥글고 매끄러워져요.", "key": "이동 · 부딪힘 · 깎임 → 둥글고 매끄러운 돌", "question": "강물을 따라 이동한 돌은 왜 더 둥글어질까요?", "answer": "이동하며 다른 돌과 부딪히고 깎여 뾰족한 부분이 닳기 때문이에요. 모든 돌이 같은 모양인 것은 아니에요.", "source": "중류1.pdf", "sourceCard": 1}, {"id": "3-1", "name": "모래톱", "region": "하류", "title": "강물이 쌓아 놓은 모래의 쉼터", "body": "강물이 운반한 모래가 쌓이면 모래밭이나 작은 모래섬이 생겨요. 이것이 모래톱이에요. 낙동강 하류에서는 새들이 쉬거나 먹이를 찾는 장소가 돼요.", "key": "모래가 쌓임 → 모래톱 → 새들의 쉼터", "question": "강물이 운반한 모래가 쌓인 모래밭이나 작은 섬을 무엇이라고 할까요?", "answer": "모래톱이에요. 새가 쉬는 곳에는 가까이 다가가지 않고 멀리서 관찰해요.", "source": "하류1.pdf", "sourceCard": 1}, {"id": "4-1", "name": "습지", "region": "습지", "title": "물을 머금은 생명의 보금자리", "body": "물이 고여 있거나 땅이 물에 젖어 있는 곳을 습지라고 해요. 물을 저장하고 천천히 흘려보내 홍수 피해를 줄이는 데 도움을 주며, 여러 동식물의 보금자리가 돼요.", "key": "물 저장 · 천천히 흘려보내기 · 다양한 생물의 서식지", "question": "습지는 생물에게 어떤 도움을 줄까요?", "answer": "여러 동식물이 살고 먹이를 찾으며 번식할 공간을 제공해요. 습지는 상류·중류·하류 어디에도 있을 수 있어요.", "source": "습지1.pdf", "sourceCard": 1}];
const LEARNING_SPECIES=[{"id": "1-3", "name": "수달", "region": "상류", "kind": "포유류", "title": "물갈퀴를 가진 강의 사냥꾼", "look": "갈색 털과 긴 꼬리, 발가락 사이의 물갈퀴가 있어요.", "life": "하천과 호숫가에서 살며 물고기를 주로 먹어요. 주로 밤에 활동해요.", "key": "물갈퀴 · 물고기 · 물가의 보금자리", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000053328", "warning": false}, {"id": "1-4", "name": "쉬리", "region": "상류", "kind": "물고기", "title": "자갈 여울에 사는 우리 물고기", "look": "몸이 가늘고 길며 머리가 뾰족해요.", "life": "맑은 하천 중·상류의 자갈 바닥 여울에 살아요. 물속 곤충과 작은 동물을 먹어요.", "key": "맑은 물 · 자갈 바닥 · 여울", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000057552", "warning": false}, {"id": "1-5", "name": "이끼", "region": "상류", "kind": "식물 무리", "title": "촉촉한 바위 위의 초록 융단", "look": "습한 바위나 땅에 작은 초록색 식물들이 모여 자라요.", "life": "물기가 많고 그늘진 곳에서 볼 수 있어요. 꽃이 피지 않고 포자로 번식해요. 물과 습기를 흡수하고 작은 생물들이 살아갈 공간을 제공하기도 해요.", "key": "습한 바위 · 작은 초록 식물 · 포자", "source": "상류2.pdf · 2번째 카드", "warning": false}, {"id": "2-2", "name": "흰목물떼새", "region": "중류", "kind": "새", "title": "자갈밭에 둥지를 만드는 작은 새", "look": "목 주변이 희고 가슴에는 검은 띠가 있어요.", "life": "강가의 자갈밭과 모래밭에서 살아요. 자갈 사이 땅을 오목하게 파서 알을 낳아요.", "key": "자갈밭 · 땅 위의 알 · 멀리서 관찰", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000155046", "warning": false}, {"id": "2-3", "name": "왜가리", "region": "중류", "kind": "새", "title": "긴 다리로 물가를 걷는 사냥꾼", "look": "회색 등과 긴 목, 긴 다리, 뾰족한 부리가 특징이에요.", "life": "강과 논, 하구 등 여러 물가에서 물고기뿐 아니라 개구리와 새우 등도 먹어요.", "key": "회색 몸 · 긴 다리 · 뾰족한 부리", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000001541", "warning": false}, {"id": "2-4", "name": "물억새", "region": "중류", "kind": "식물", "title": "강가에서 은빛 이삭을 흔드는 풀", "look": "키가 크고 가늘고 긴 잎이 나요. 땅속줄기가 길게 뻗어요.", "life": "강가와 습지에 자라는 여러해살이풀이에요. 꽃이삭은 처음 갈색이었다가 은백색으로 변해요.", "key": "물가 · 무리 지은 풀 · 은백색 꽃이삭", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000064979", "warning": false}, {"id": "2-5", "name": "피라미", "region": "중류", "kind": "물고기", "title": "중류 여울의 은빛 물고기", "look": "몸이 길고 옆으로 납작하며 배 쪽이 은백색이에요.", "life": "맑은 하천 중류의 여울에서 볼 수 있어요. 물속 곤충의 애벌레나 돌에 붙은 조류를 먹어요.", "key": "중류 여울 · 은백색 배 · 작은 민물고기", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000057645", "warning": false}, {"id": "3-2", "name": "큰고니", "region": "하류", "kind": "새", "title": "겨울에 찾아오는 하얀 손님", "look": "어른 새는 흰색이고 목이 길어요. 부리는 노란색과 검은색이에요.", "life": "낙동강 하구에서 겨울을 나는 철새예요. 얕은 물에서 식물의 뿌리나 작은 수중생물을 먹어요.", "key": "겨울철새 · 흰 몸 · 노랑과 검정 부리", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000001427", "warning": false}, {"id": "3-3", "name": "뱀장어", "region": "하류", "kind": "물고기", "title": "강과 바다를 오가는 긴 물고기", "look": "몸이 길고 배지느러미가 없어요. 등·꼬리·뒷지느러미가 이어져 있어요.", "life": "여러 하천과 호수에 살아요. 낮에는 돌 밑이나 진흙 속에 숨고 밤에 먹이를 찾아요. 민물에서 바다로 이동해요.", "key": "길쭉한 몸 · 밤 활동 · 강과 바다의 연결", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000057414", "warning": false}, {"id": "3-4", "name": "재첩", "region": "하류", "kind": "조개", "title": "단단한 두 껍데기를 가진 조개", "look": "두껍고 단단한 껍데기는 둥근 삼각형에 가까워요.", "life": "하천의 모래 바닥에 살아요. 공식 종 설명에는 중류 서식도 나와 있어요. 하류에만 사는 생물은 아니에요.", "key": "조개 · 두 장의 껍데기 · 모래 바닥", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000213056", "warning": false}, {"id": "3-5", "name": "갈대", "region": "하류", "kind": "식물", "title": "물가를 채우는 키 큰 풀", "look": "긴 줄기와 잎을 가진 여러해살이풀이에요. 땅속줄기가 길게 뻗어요.", "life": "습지와 냇가에서 자라요. 가을에는 줄기 끝에 붉은 갈색 꽃이삭이 달려요.", "key": "습지 · 키 큰 풀 · 갈색 꽃이삭", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000074592", "warning": false}, {"id": "4-2", "name": "맹꽁이", "region": "습지", "kind": "양서류", "title": "비 오는 여름의 작은 합창단", "look": "몸이 둥글고 다리가 짧아요. 등에는 작은 돌기가 있어요.", "life": "평소에는 흙 속에 숨어 지내다가 주로 밤에 활동해요. 장마철 물이 고인 곳에서 번식해요.", "key": "둥근 몸 · 장마철 · 물웅덩이", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000001384", "warning": false}, {"id": "4-3", "name": "재두루미", "region": "습지", "kind": "새", "title": "가족과 함께 겨울을 나는 새", "look": "몸은 회색이고 머리와 뒷목은 희며 눈 주변이 붉어요.", "life": "습지와 논, 강 하구에서 먹이를 찾아요. 구미 해평습지와 낙동강 하구 등에서도 일부가 겨울을 나요.", "key": "회색 몸 · 흰 머리 · 겨울철새", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000001650", "warning": false}, {"id": "4-4", "name": "가시연꽃", "region": "습지", "kind": "식물", "title": "가시 돋친 큰 잎을 물에 띄워요", "look": "물 위에 넓은 잎이 뜨고 잎맥에 가시가 있어요. 꽃은 밝은 자주색이에요.", "life": "연못과 저수지에서 자라는 한해살이풀이에요. 공식 종명은 가시연이며 가시연꽃이라고도 불러요.", "key": "넓은 뜬잎 · 가시 · 자주색 꽃", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000060115", "warning": false}, {"id": "4-5", "name": "물방개", "region": "습지", "kind": "곤충", "title": "물속에서 헤엄치는 딱정벌레", "look": "몸은 길쭉한 타원형이고 등은 녹색을 띤 검은색이에요.", "life": "수초가 많은 연못과 늪 등에 살아요. 성충과 애벌레 모두 작은 수중동물을 먹어요. 물 위에서 공기를 저장해 숨 쉬어요.", "key": "수서곤충 · 타원형 몸 · 공기 저장", "source": "https://fbp.nnibr.re.kr/portal/search/res/read_ktsn.do?sel_menu_code=_portal_search_menu1&ktsn=120000214190", "warning": false}];
const learnRegions=['상류','중류','하류','습지'];const learnColors=['#2f7746','#286d9f','#aa631b','#8050a0'];
const learnHabitats=[
'산과 계곡에서 시작하는 강! 게임에서는 좁은 강폭과 빠른 물살을 함께 배워요. 실제 강의 폭과 흐름은 지형과 물의 양에 따라 달라져요.',
'여울과 자갈밭, 모래밭이 만나는 곳! 둥근 돌은 이동하며 부딪히고 깎인 흔적이에요. 물속 생물과 강가의 새, 풀을 함께 살펴봐요.',
'강물이 바다를 향해 가는 곳! 모래가 쌓인 모래톱은 새들이 쉬는 장소가 돼요. 강과 바다가 이어지는 길도 생물에게 중요해요.',
'물이 고이거나 땅이 물에 젖어 있는 곳! 습지는 강의 상류·중류·하류 어디에도 있을 수 있어요. 서로 다른 생물의 보금자리를 찾아봐요.'
];
const learningDialog=document.createElement('dialog');learningDialog.id='learningDialog';learningDialog.setAttribute('aria-labelledby','learningTitle');learningDialog.innerHTML='<div class="learn-head"><div><div class="learn-eyebrow">게임 전 생태 탐험 · 자연환경 5개 + 생물 15개</div><h2 id="learningTitle">낙동강의 자연환경과 대표 생물들</h2></div><button id="closeLearning">닫기 ×</button></div><p class="learn-intro">수달과 함께 <strong>강의 특징과 생물의 생김새·사는 곳</strong>을 먼저 알아봐요. 아래 구역을 차례로 읽으면 미션을 푸는 데 도움이 돼요.<br><a class="learn-official" href="https://fbp.nnibr.re.kr/portal/" target="_blank" rel="noopener">국립낙동강생물자원관 담수생물다양성 정보포털</a> 종 정보와 사용자 확정 원본 미션카드의 자연환경 설명을 바탕으로 쉽게 정리했어요.</p><nav class="learn-tabs" role="tablist" aria-label="학습 구역"></nav><div class="learn-body" id="learningPanel" role="tabpanel"></div>';document.body.append(learningDialog);
let learningRegion=0;const learnedRegions=new Set();let learningFocus=null;
