const worldRenderLearning=renderLearning;renderLearning=function(index){worldRenderLearning(index);const panel=document.getElementById('learningPanel');const cards=[...panel.querySelectorAll('.learn-card')];const grids=[...panel.querySelectorAll('.learn-grid')];const headings=[...panel.querySelectorAll('.learn-section-title')];let current=0;const nav=document.createElement('div');nav.className='world-lesson-nav';const prev=document.createElement('button');prev.textContent='← 이전';const count=document.createElement('span');count.setAttribute('aria-live','polite');const next=document.createElement('button');next.textContent='다음 발견 →';nav.append(prev,count,next);panel.querySelector('.learn-habitat').after(nav);function turn(n){current=n;cards.forEach((c,i)=>c.hidden=i!==n);grids.forEach(g=>{g.classList.add('world-single');g.hidden=![...g.querySelectorAll('.learn-card')].includes(cards[n])});headings.forEach(h=>h.hidden=true);count.textContent=learnRegions[index]+' 발견 '+(n+1)+' / '+cards.length;prev.disabled=n===0;next.disabled=n===cards.length-1}prev.onclick=()=>turn(Math.max(0,current-1));next.onclick=()=>turn(Math.min(cards.length-1,current+1));turn(0)};

