function showRegionCelebration(region,preview=false){if(!learnRegions.includes(region))return;if(regionCelebration.open){regionPartyQueue.push({region,preview});return}const party=regionCelebration.firstElementChild;party.style.setProperty('--party-color',REGION_PARTY_COLORS[region]);document.getElementById('regionPartyTag').textContent=preview?'생태계칩 5 / 5 · 구역 복원 미리보기':'생태계칩 5 / 5 · 구역 완성 보너스 +100p';document.getElementById('regionPartyTitle').textContent=region+' 미션 완성!';document.getElementById('regionPartyMessage').textContent='수달이와 힘을 모아 '+region+'의 생태계칩을 모두 모았어요. 수달이도 함께 축하해요!';document.getElementById('regionPartyNote').textContent=preview?'연출 미리보기 · 점수와 진행 기록은 바뀌지 않아요.':'생태계칩 5개 복원 완료 · 구역 보너스 +100p가 합산됐어요.';const chips=document.getElementById('regionPartyChips');chips.replaceChildren();MISSION_DATA.filter(m=>m.region===region).forEach((m,i)=>{const im=document.createElement('img');im.src=CHIP_ASSETS[m.id].image;im.alt=m.chip;im.style.setProperty('--i',i);chips.append(im)});party.querySelectorAll('.region-confetti').forEach(e=>e.remove());for(let i=0;i<24;i++){const bit=document.createElement('i');bit.className='region-confetti';bit.setAttribute('aria-hidden','true');bit.style.setProperty('--x',(i*4.25)+'%');bit.style.setProperty('--c',['#ffcb3b','#48bdc7','#f4879d',REGION_PARTY_COLORS[region]][i%4]);bit.style.setProperty('--d',(i%7*.16)+'s');party.append(bit)}regionPartyFocus=document.activeElement;regionCelebration.showModal();document.getElementById('closeRegionParty').focus();clearTimeout(regionPartyTimer);regionPartyTimer=setTimeout(()=>regionCelebration.close(),6000)}
document.getElementById('closeRegionParty').onclick=()=>regionCelebration.close();regionCelebration.addEventListener('close',()=>{clearTimeout(regionPartyTimer);if(regionPartyQueue.length){const next=regionPartyQueue.shift();showRegionCelebration(next.region,next.preview);return}if(pendingRegionRank){const args=pendingRegionRank;pendingRegionRank=null;regionRankOriginal(...args);return}if(regionPartyFocus?.isConnected)regionPartyFocus.focus({preventScroll:true})});
