function recordTotal(){return missionTotalPoints()}
function updateRecordEntry(){const profile=soloExplorerProfile,total=recordTotal(),chips=missionGame.completed.size;document.getElementById('myRecordSummary').textContent=profile?profile.school+' · '+profile.name+' · '+total+'p · 생태계칩 '+chips+'/20':'탐험 홈에서 학교명과 탐험자명을 입력해 주세요.';const saved=localStorage.getItem('nakdong-record-saved-v1')===recordsRunId+':'+total+':'+chips;submitRecord.disabled=!profile||(total<200&&chips<10)||!profile.recordsConsent||recordSending||saved;if(!recordSending)recordStatus.textContent=saved?'이 탐험의 기록을 저장했어요.':!profile?.recordsConsent?'탐험자 소개에서 최고 기록 공개에 동의한 경우 기록을 남길 수 있어요.':(total<200&&chips<10)?'200p 이상 또는 생태계칩 10개 이상이면 기록을 남길 수 있어요.':'기록 조건을 달성했어요! 다시 저장하면 같은 날 같은 참가자 코드의 기록을 최신 최고 점수로 갱신해요.';}
function loadRecords(){const status=document.getElementById('recordsLoadStatus');status.textContent='기록을 불러오는 중이에요…';const cb='nakdongRecords_'+crypto.randomUUID().replace(/-/g,'');const script=document.createElement('script');let timeout;function cleanup(){clearTimeout(timeout);script.remove();delete window[cb]}
window[cb]=result=>{cleanup();const rows=document.getElementById('recordsRows');rows.replaceChildren();if(!result.ok){status.textContent=result.error||'기록을 불러오지 못했어요.';return}for(const r of result.records||[]){const tr=document.createElement('tr');for(const value of [r.school,r.name,r.rank,r.score+'p']){const td=document.createElement('td');td.textContent=String(value);tr.append(td)}rows.append(tr)}status.textContent=result.records?.length?'':'아직 등록된 기록이 없어요. 첫 탐험 기록을 남겨 보세요!'};script.onerror=()=>{cleanup();status.textContent='연결하지 못했어요. 새로고침으로 다시 시도해 주세요.'};timeout=setTimeout(()=>{cleanup();status.textContent='응답이 늦어지고 있어요. 새로고침으로 다시 시도해 주세요.'},20000);script.src=RECORDS_ENDPOINT+'?callback='+cb;document.head.append(script);}
