submitRecord.onclick=()=>{updateRecordEntry();if(submitRecord.disabled)return;recordSending=true;submitRecord.disabled=true;recordStatus.textContent='기록을 저장하고 있어요…';recordPendingSnapshot={runId:recordsRunId,total:recordTotal(),chips:missionGame.completed.size};const payload={version:'solo-v6',participantId:soloExplorerProfile.participantId,shufflePenalty:pointsState.shufflePenalty||0,consented:Boolean(soloExplorerProfile.recordsConsent),runId:recordsRunId,school:soloExplorerProfile.school,name:soloExplorerProfile.name,awards:Object.fromEntries([...missionGame.completed].map(id=>[id,pointsState.awards[id]||0]))};const form=document.createElement('form');form.method='POST';form.action=RECORDS_ENDPOINT;form.target=recordFrame.name;form.hidden=true;for(const [name,value] of Object.entries({payload:JSON.stringify(payload),runId:recordsRunId})){const input=document.createElement('input');input.name=name;input.value=value;form.append(input)}document.body.append(form);form.submit();form.remove();recordTimer=setTimeout(()=>{recordSending=false;updateRecordEntry();recordStatus.textContent='저장 확인이 늦어지고 있어요. 다시 눌러도 같은 탐험은 중복 저장되지 않아요.'},25000);};
window.addEventListener('message',event=>{if(!/^https:\/\/([a-z0-9-]+-)?script\.googleusercontent\.com$/.test(event.origin)&&event.origin!=='https://script.google.com')return;const data=event.data;if(!recordSending||data?.type!=='nakdong-record-saved'||data.runId!==recordsRunId)return;clearTimeout(recordTimer);recordSending=false;if(data.ok&&recordPendingSnapshot?.runId===recordsRunId)localStorage.setItem('nakdong-record-saved-v1',recordsRunId+':'+recordPendingSnapshot.total+':'+recordPendingSnapshot.chips);updateRecordEntry();recordStatus.textContent=data.ok?'기록 처리 완료 · 오늘 최고 '+data.score+'p. 현재 점수보다 낮은 점수로는 기존 최고점을 덮어쓰지 않아요.':data.error||'저장하지 못했어요. 다시 시도해 주세요.';if(data.ok)loadRecords()});
