function regionCompletionBonus(completed,missions){const ids=new Set(completed);return ['상류','중류','하류','습지'].filter(r=>{const group=missions.filter(m=>m.region===r);return group.length===5&&group.every(m=>ids.has(m.id))}).length*100}
function applyShufflePenalty(){const deducted=missionTotalPoints()>0;if(deducted)pointsState.shufflePenalty=(pointsState.shufflePenalty||0)+1;return deducted}
function missionTotalPoints(){return Math.max(0,[...missionGame.completed].reduce((sum,id)=>sum+(pointsState.awards[id]||0),0)+regionCompletionBonus(missionGame.completed,MISSION_DATA)-(pointsState.shufflePenalty||0))}
function updateExplorerRegionBadges(){const identity=document.getElementById('explorerIdentity');if(!identity)return;let row=identity.querySelector('.explorer-name-row');if(!row){row=document.createElement('div');row.className='explorer-name-row';const name=identity.querySelector('.explorer-name');name.before(row);row.append(name)}let badges=row.querySelector('.explorer-region-badges');if(!badges){badges=document.createElement('span');badges.className='explorer-region-badges';badges.setAttribute('aria-label','완성한 구역');row.append(badges)}badges.replaceChildren();for(const region of ['상류','중류','하류','습지']){const group=MISSION_DATA.filter(m=>m.region===region);if(!group.every(m=>missionGame.completed.has(m.id)))continue;const badge=document.createElement('span');badge.className='explorer-region-badge';badge.textContent=region;badge.title=region+' 완성 · 보너스 +100p';badge.style.setProperty('--badge-color',regionColors[region]);badges.append(badge)}}
