function showLearningResults(){missionTitle.textContent='나의 생태 탐험 학습 결과';missionContent.replaceChildren();const intro=document.createElement('p');intro.className='mission-note';intro.textContent=(soloExplorerProfile?.name||'나')+' · 현재 '+missionTotalPoints()+'p · 생태계칩 '+missionGame.completed.size+'/20 · 힌트·오답은 이번 버전에서 기록한 내역을 집계해요.';missionContent.append(intro);const rows=document.createElement('div');rows.className='learning-result-grid';for(const region of learnRegions){const missions=MISSION_DATA.filter(m=>m.region===region);const item=document.createElement('section');item.className='mission-section';const h=document.createElement('h3');h.textContent=region+' · '+missions.filter(m=>missionGame.completed.has(m.id)).length+'/5 복원';const p=document.createElement('p');p.textContent='힌트 '+missions.filter(m=>(pointsState.history?.[m.id]||pointsState.clocks[m.id])?.hinted).length+'문항 · 오답 '+missions.reduce((n,m)=>n+((pointsState.history?.[m.id]||pointsState.clocks[m.id])?.wrongCount||0),0)+'회';item.append(h,p);rows.append(item)}missionContent.append(rows);const review=document.createElement('section');review.className='mission-section';const title=document.createElement('h3');title.textContent='다시 읽고 기억하기 · 점수 변동 없음';review.append(title);const ids=new Set([...missionGame.completed,...(pointsState.learningReviews||[])]);for(const m of MISSION_DATA.filter(m=>ids.has(m.id))){const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent=m.region+' · '+m.chip;const image=document.createElement('img');image.src=CHIP_ASSETS[m.id].image;image.alt=m.chip;image.width=100;image.loading='lazy';const text=document.createElement('p');text.textContent=m.explanation;details.append(summary,image,text);review.append(details)}if(!ids.size){const empty=document.createElement('p');empty.textContent='미션에 도전하면 배운 내용이 여기에 모여요.';review.append(empty)}missionContent.append(review);const pledge=document.createElement('label');pledge.className='pledge-box';pledge.textContent='🌿 낙동강을 위해 내가 실천할 약속';const field=document.createElement('textarea');field.maxLength=160;field.rows=2;field.placeholder='예: 물가에 쓰레기를 버리지 않고 생물을 괴롭히지 않을래요.';field.value=pointsState.pledge||'';field.oninput=()=>{pointsState.pledge=field.value;savePoints()};pledge.append(field);const close=document.createElement('button');close.textContent='보드로 돌아가기';close.className='guide-primary';close.onclick=()=>missionDialog.close();missionContent.append(pledge,close);openMissionDialog()}
